import { NextRequest, NextResponse } from 'next/server';

// NOTE: Authentication is handled client-side via the protected layout
// because tokens are stored in localStorage (not accessible server-side).
// This middleware is disabled to allow client-side auth checks.
export function middleware(request: NextRequest) {
  // Allow all requests - client-side protected layout will handle auth
  return NextResponse.next();
}

// Apply middleware to specific paths
export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    '/((?!api|_next/static|_next/image|favicon.ico).*)',
  ],
};